"use client";

import { getProperty } from "@/api/property";
import { TableBody, TableCaption, TableCell, TableFooter, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Property } from "@/types/properties";

import axios from "axios";
import { Table } from "lucide-react";
import React, { useEffect, useState } from "react";

const DataProperties = () => {
  const [data, setData] = useState<Property[]>([]);

  useEffect(() => {
    const fetchData = async () => {
      try {
        const res = await getProperty();
        setData(res.data);
        console.log("Data property : ", res.data);
      } catch (error: unknown) {
        if (axios.isAxiosError(error)) {
          console.error("Error dari axios:", error.response?.data || error.message);
        } else {
          console.error("Error umum:", (error as Error).message);
        }
      }
    };
    fetchData();
  }, []);

  return (
    <>
      <Table>
        <TableCaption>A list of properties.</TableCaption>
        <TableHeader>
          <TableRow>
            <TableHead className="w-[100px]">Name</TableHead>
            <TableHead>Status</TableHead>
            <TableHead>Price</TableHead>
            <TableHead className="text-right">Price Unit</TableHead>
            <TableHead>Currency</TableHead>
            <TableHead>Description</TableHead>
          </TableRow>
        </TableHeader>
        <TableBody>
          {data.length === 0 ? (
            <TableRow>
              <TableCell colSpan={6} className="text-center text-muted-foreground">
                Belum ada data properti
              </TableCell>
            </TableRow>
          ) : (
            data.map((property: Property) => (
              <TableRow key={property.id}>
                <TableCell className="font-medium">{property.name}</TableCell>
                <TableCell>{property.status}</TableCell>
                <TableCell>{property.price}</TableCell>
                <TableCell>{property.price_unit}</TableCell>
                <TableCell className="text-right">{property.currency}</TableCell>
                <TableCell>{property.description}</TableCell>
              </TableRow>
            ))
          )}
        </TableBody>
        <TableFooter>
          <TableRow>
            <TableCell colSpan={3}>Total</TableCell>
            <TableCell className="text-right">$2,500.00</TableCell>
          </TableRow>
        </TableFooter>
      </Table>
    </>
  );
};

export default DataProperties;
